            200,
            "application/json",
            "[{\"a\":{\"id\":1,\"name\":\"Dogs\"}},{\"b\":{\"id\":2,\"name\":\"Cats\"}}]"
        );

        var result = await mockApi.GetGroupedCategoriesAsync();

        Assert.NotNull(result);
        Assert.Equal(2, result.Count);

        var first = result[0]["a"];
        Assert.IsType<Category>(first);
        Assert.Equal(1L, first.Id);
        Assert.Equal("Dogs", first.Name);

        var second = result[1]["b"];
        Assert.IsType<Category>(second);
        Assert.Equal(2L, second.Id);
        Assert.Equal("Cats", second.Name);
    }

